draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  for (let i = 0; i < 360; i += 30) {
    ctx.beginPath();
    ctx.arc(W / 2, H / 2, 100 + 50 * Math.sin(t + i / 10), 0, 2 * Math.PI);
    ctx.stroke();
  }
  for (let i = 0; i < 360; i += 30) {
    ctx.beginPath();
    ctx.arc(W / 2, H / 2, 150 + 50 * Math.cos(t + i / 10), 0, 2 * Math.PI);
    ctx.stroke();
  }
  ctx.fillStyle = 'black';
  ctx.font = '48px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('369', W / 2, H / 2);
  ctx.restore();
}
